axie-origin-market"]}]},"sources":[{"id":"axie-roadmap","title":"Axie Infinity — Roadmap and completed milestones","url":"https://whitepaper.axieinfinity.com/roadmap","publisher":"Axie Infinity","source_date":"2018-02-01","source_date_kind":"event","last_verified_at":"2026-07-29","evidence_scope":"historical_event","stale_after":null,"stale":false,"checked_at":"2026-07-29"},{"id":"axie-origin-market","title":"App.Axie — Origin Axies collection","url":"https://app.axieinfinity.com/marketplace/axies/origin/","publisher":"Sky Mavis","source_date":"2018-04-30","source_date_kind":"event","last_verified_at":"2026-07-29","evidence_scope":"mechanism","stale_after":null,"stale":false,"checked_at":"2026-07-29"},{"id":"axie-current","title":"Axie Infinity — Origins Season 18 is live","url":"https://blog.axieinfinity.com/p/origins-s18-is-live","publisher":"Sky Mavis","source_date":"2026-07-08","source_date_kind":"published","last_verified_at":"2026-07-29","evidence_scope":"current_state","stale_after":"2026-10-06","stale":false,"checked_at":"2026-07-29"}]},{"slug":"tezzardz","name":"Tezzardz","chain":"tezos","category":"pfp-art","status":"unknown","profile":{"citation_schema":"field-v1","evidence_policy":{"schema":"forensic-freshness-v1","status_basis":"withheld","status_as_of":"2025-04-03","last_verified_at":"2026-07-29","next_review_at":"2026-08-29","stale":true},"launched":"2021-09","supply":4200,"founder_engagement":"A current Tezos ecosystem editorial continues to identify creator George Goodwin and feature Tezzardz as a recognized Tezos PFP collection; no recurring operator roadmap is evidenced.","benefits":"The cited proposition is a finite, artist-created generative PFP collection; no contractual game, token, or revenue utility is asserted.","analysis":"Current lifecycle classification is withheld: the collection retains official ecosystem recognition and a clear artist/provenance record, while the evidence does not establish a recurring operating product or current liquidity.","evidence":[{"field":"launch","value":"2021-09 — launched and sold out in under two hours","as_of":"2025-04-03","basis":"editorial","source_ids":["tezzardz-spotlight"]},{"field":"supply_or_mint","value":"4,200 programmatically generated Tezos PFPs","as_of":"2025-04-03","basis":"editorial","source_ids":["tezzardz-spotlight"]},{"field":"lifecycle_status","value":"unknown — current lifecycle withheld because dated evidence is stale for current operations or market depth","as_of":"2025-04-03","basis":"analyst","source_ids":["tezzardz-spotlight","tezzardz-market"]},{"field":"founder_engagement","value":"Current Tezos ecosystem editorial credits artist George Goodwin and continues to feature the collection; no recurring roadmap is asserted","as_of":"2025-04-03","basis":"editorial","source_ids":["tezzardz-spotlight"]},{"field":"benefits","value":"Finite artist-created generative PFP provenance; no contractual game, token, or revenue utility asserted","as_of":"2025-04-03","basis":"editorial","source_ids":["tezzardz-spotlight"]},{"field":"analysis","value":"Current lifecycle withheld because ecosystem recognition does not establish an active operating product or liquid market","as_of":"2025-04-03","basis":"analyst","source_ids":["tezzardz-spotlight","tezzardz-market"]}]},"sources":[{"id":"tezzardz-spotlight","title":"Tezos Spotlight — Celebrating PFPs on Tezos","url":"https://spotlight.tezos.com/pfps-on-tezos/","publisher":"Tezos Spotlight","source_date":"2025-04-03","source_date_kind":"published","last_verified_at":"2026-07-29","evidence_scope":"historical_event","stale_after":null,"stale":false,"checked_at":"2026-07-29"},{"id":"tezzardz-market","title":"Objkt — Tezzardz collection","url":"https://objkt.com/collections/tezzardz","publisher":"Objkt","source_date":null,"source_date_kind":"unknown","last_verified_at":"2026-07-29","evidence_scope":"mechanism","stale_after":null,"stale":false,"checked_at":"2026-07-29"}]}]')
)
INSERT OR REPLACE INTO nft_collections
  (slug, name, chain, category, status, profile, sources, updated_at)
SELECT
  json_extract(value, '$.slug'),
  json_extract(value, '$.name'),
  json_extract(value, '$.chain'),
  json_extract(value, '$.category'),
  json_extract(value, '$.status'),
  json_extract(value, '$.profile'),
  json_extract(value, '$.sources'),
  '2026-07-29'
FROM dossier_seed, json_each(dossier_seed.payload);
